def get_connection_name(ssid: str) -> Optional[str]:
    """ Get the nmcli connection name for the given SSID.

    Returns None if no such connection is found.
    """
    cmd = [
        "nmcli", "connection", "show",
        "--active",
        "--no-legend",
        "--no-header",
        "--only", "UUID,SSID",
    ]
    try:
        output = subprocess.check_output(cmd)
    except subprocess.CalledProcessError:
        return None

    for line in output.splitlines():
        uuid, ssid = line.decode("utf-8").strip().split(":")
        if ssid == ssid:
            return uuid

    return None


def connection_exists(ssid: str) -> bool:
    """ Check if a connection with the given SSID exists.

    Returns True if it does, False if it doesn't.
    """
    return get_connection_name(ssid) is not None


